1	import fs from 'fs';
2	import path from 'path';
3	import Handlebars from 'handlebars';
4	
5	export interface TemplateConfig {
6	  templatesDir: string;
7	  layoutsDir: string;
8	  partialsDir: string;
9	  defaultLayout?: string;
10	  defaultTemplate?: string;
11	}
12	
13	type TemplateFunction = (context: Record<string, unknown>) => string;
14	
15	export class TemplateEngine {
16	  private config: TemplateConfig;
17	  private templates: Map<string, TemplateFunction> = new Map();
18	  private layouts: Map<string, TemplateFunction> = new Map();
19	  private partialsLoaded: boolean = false;
20	
21	  constructor(config: TemplateConfig) {
22	    this.config = {
23	      templatesDir: config.templatesDir || './templates',
24	      layoutsDir: config.layoutsDir || './templates/layouts',
25	      partialsDir: config.partialsDir || './templates/partials',
26	      defaultLayout: config.defaultLayout || 'default',
27	      defaultTemplate: config.defaultTemplate || 'page',
28	    };
29	  }
30	
31	  private loadPartials(): void {
32	    if (this.partialsLoaded) return;
33	
34	    if (!fs.existsSync(this.config.partialsDir)) {
35	      this.partialsLoaded = true;
36	      return;
37	    }
38	
39	    const partialsFiles = fs.readdirSync(this.config.partialsDir);
40	    for (const file of partialsFiles) {
41	      if (file.endsWith('.hbs')) {
42	        const partialPath = path.join(this.config.partialsDir, file);
43	        const partialContent = fs.readFileSync(partialPath, 'utf-8');
44	        const partialName = file.replace(/\.hbs$/, '');
45	        Handlebars.registerPartial(partialName, partialContent);
46	      }
47	    }
48	
49	    this.partialsLoaded = true;
50	  }
51	
52	  getTemplatePath(templateName: string): string {
53	    return path.join(this.config.templatesDir, `${templateName}.hbs`);
54	  }
55	
56	  getLayoutPath(layoutName: string): string {
57	    return path.join(this.config.layoutsDir, `${layoutName}.hbs`);
58	  }
59	
60	  loadTemplate(templateName: string): TemplateFunction {
61	    if (this.templates.has(templateName)) {
62	      return this.templates.get(templateName)!;
63	    }
64	
65	    this.loadPartials();
66	
67	    const templatePath = this.getTemplatePath(templateName);
68	    if (!fs.existsSync(templatePath)) {
69	      throw new Error(`Template not found: ${templatePath}`);
70	    }
71	
72	    const templateContent = fs.readFileSync(templatePath, 'utf-8');
73	    const compiled = Handlebars.compile(templateContent);
74	    this.templates.set(templateName, compiled);
75	    return compiled;
76	  }
77	
78	  loadLayout(layoutName: string): TemplateFunction {
79	    if (this.layouts.has(layoutName)) {
80	      return this.layouts.get(layoutName)!;
81	    }
82	
83	    this.loadPartials();
84	
85	    const layoutPath = this.getLayoutPath(layoutName);
86	    if (!fs.existsSync(layoutPath)) {
87	      throw new Error(`Layout not found: ${layoutPath}`);
88	    }
89	
90	    const layoutContent = fs.readFileSync(layoutPath, 'utf-8');
91	    const compiled = Handlebars.compile(layoutContent);
92	    this.layouts.set(layoutName, compiled);
93	    return compiled;
94	  }
95	
96	  renderTemplate(
97	    templateName: string,
98	    context: Record<string, unknown>
99	  ): string {
100	    const template = this.loadTemplate(templateName);
101	    return template(context);
102	  }
103	
104	  renderLayout(
105	    layoutName: string,
106	    context: Record<string, unknown>
107	  ): string {
108	    const layout = this.loadLayout(layoutName);
109	    return layout(context);
110	  }
111	
112	  renderPageWithLayout(
113	    pageContent: string,
114	    layoutName: string,
115	    context: Record<string, unknown>
116	  ): string {
117	    const layout = this.loadLayout(layoutName);
118	    return layout({
119	      ...context,
120	      body: pageContent,
121	    });
122	  }
123	
124	  hasTemplate(templateName: string): boolean {
125	    const templatePath = this.getTemplatePath(templateName);
126	    return fs.existsSync(templatePath);
127	  }
128	
129	  hasLayout(layoutName: string): boolean {
130	    const layoutPath = this.getLayoutPath(layoutName);
131	    return fs.existsSync(layoutPath);
132	  }
133	
134	  registerHelper(name: string, fn: (...args: unknown[]) => unknown): void {
135	    Handlebars.registerHelper(name, fn);
136	  }
137	}
138	
139	export function createTemplateEngine(config: Partial<TemplateConfig> = {}): TemplateEngine {
140	  return new TemplateEngine({
141	    templatesDir: './templates',
142	    layoutsDir: './templates/layouts',
143	    partialsDir: './templates/partials',
144	    ...config,
145	  });
146	}
