1	import http from 'http';
2	import fs from 'fs';
3	import path from 'path';
4	import { WebSocketServer, WebSocket } from 'ws';
5	import { watch } from 'chokidar';
6	import { build } from './generator';
7	
8	interface DevServerOptions {
9	  contentDir: string;
10	  outputDir: string;
11	  templatesDir: string;
12	  port: number;
13	}
14	
15	let isBuilding = false;
16	let buildPending = false;
17	
18	export class DevServer {
19	  private server: http.Server;
20	  private wss: WebSocketServer;
21	  private options: DevServerOptions;
22	
23	  constructor(options: DevServerOptions) {
24	    this.options = options;
25	    this.server = http.createServer((req, res) => this.handleRequest(req, res));
26	    this.wss = new WebSocketServer({ server: this.server });
27	  }
28	
29	  private async handleRequest(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
30	    if (!req.url) {
31	      res.writeHead(404);
32	      res.end('Not found');
33	      return;
34	    }
35	
36	    let filePath = req.url;
37	    if (filePath === '/') {
38	      filePath = 'index.html';
39	    } else if (filePath.startsWith('/')) {
40	      filePath = filePath.slice(1);
41	    }
42	
43	    const fullPath = path.join(this.options.outputDir, filePath);
44	
45	    if (!fs.existsSync(fullPath)) {
46	      res.writeHead(404);
47	      res.end('Not found');
48	      return;
49	    }
50	
51	    let content = fs.readFileSync(fullPath, 'utf-8');
52	
53	    if (filePath.endsWith('.html')) {
54	      content = this.injectLiveReloadScript(content);
55	    }
56	
57	    const contentType = filePath.endsWith('.html') ? 'text/html' : 'application/octet-stream';
58	    res.writeHead(200, { 'Content-Type': contentType });
59	    res.end(content);
60	  }
61	
62	  private injectLiveReloadScript(html: string): string {
63	    const script = `<script>
64	(function() {
65	  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
66	  const ws = new WebSocket(protocol + '//' + window.location.host);
67	  ws.onmessage = function(event) {
68	    if (event.data === 'rebuild-complete') {
69	      window.location.reload();
70	    }
71	  };
72	})();
73	</script>`;
74	
75	    if (html.includes('</body>')) {
76	      return html.replace('</body>', `${script}</body>`);
77	    }
78	    return html + script;
79	  }
80	
81	  private notifyClients(message: string): void {
82	    this.wss.clients.forEach((client: WebSocket) => {
83	      if (client.readyState === 1) {
84	        client.send(message);
85	      }
86	    });
87	  }
88	
89	  private async rebuild(): Promise<void> {
90	    if (isBuilding) {
91	      buildPending = true;
92	      return;
93	    }
94	
95	    isBuilding = true;
96	    try {
97	      console.log('🔄 Rebuilding...');
98	      await build(this.options.contentDir, this.options.outputDir, this.options.templatesDir);
99	      console.log('✓ Rebuild complete');
100	      this.notifyClients('rebuild-complete');
101	
102	      if (buildPending) {
103	        buildPending = false;
104	        await this.rebuild();
105	      }
106	    } catch (error) {
107	      if (error instanceof Error) {
108	        console.error(`✗ Build error: ${error.message}`);
109	      } else {
110	        console.error('✗ Unknown build error');
111	      }
112	    } finally {
113	      isBuilding = false;
114	    }
115	  }
116	
117	  public start(): void {
118	    if (!fs.existsSync(this.options.outputDir)) {
119	      fs.mkdirSync(this.options.outputDir, { recursive: true });
120	    }
121	
122	    const watcher = watch([this.options.contentDir, this.options.templatesDir], {
123	      ignored: /(^|[\/\\])\./,
124	      persistent: true,
125	    });
126	
127	    watcher.on('change', () => {
128	      this.rebuild();
129	    });
130	
131	    watcher.on('add', () => {
132	      this.rebuild();
133	    });
134	
135	    watcher.on('unlink', () => {
136	      this.rebuild();
137	    });
138	
139	    this.server.listen(this.options.port, () => {
140	      console.log(`\n🚀 Dev server running at http://localhost:${this.options.port}`);
141	      console.log(`📁 Watching ${this.options.contentDir} and ${this.options.templatesDir}`);
142	      console.log(`📦 Serving from ${this.options.outputDir}\n`);
143	    });
144	  }
145	
146	  public stop(): void {
147	    this.server.close();
148	    this.wss.close();
149	  }
150	}
