1	export interface Frontmatter {
2	  title?: string;
3	  date?: string;
4	  tags?: string[];
5	  template?: string;
6	  layout?: string;
7	  [key: string]: unknown;
8	}
9	
10	export interface ParsedMarkdown {
11	  frontmatter: Frontmatter;
12	  content: string;
13	}
14	
15	function parseYamlValue(value: string): unknown {
16	  value = value.trim();
17	
18	  if (value === 'true') return true;
19	  if (value === 'false') return false;
20	  if (value === 'null' || value === '') return null;
21	
22	  if (!isNaN(Number(value))) return Number(value);
23	
24	  if (value.startsWith('[') && value.endsWith(']')) {
25	    const arrayContent = value.slice(1, -1).trim();
26	    if (!arrayContent) return [];
27	    return arrayContent.split(',').map((item) => {
28	      const trimmed = item.trim();
29	      return trimmed.startsWith('"') && trimmed.endsWith('"')
30	        ? trimmed.slice(1, -1)
31	        : trimmed;
32	    });
33	  }
34	
35	  if (value.startsWith('"') && value.endsWith('"')) {
36	    return value.slice(1, -1);
37	  }
38	
39	  return value;
40	}
41	
42	function parseYaml(yamlContent: string): Record<string, unknown> {
43	  const lines = yamlContent.split('\n');
44	  const result: Record<string, unknown> = {};
45	
46	  for (const line of lines) {
47	    if (!line.trim() || line.trim().startsWith('#')) continue;
48	
49	    const colonIndex = line.indexOf(':');
50	    if (colonIndex === -1) continue;
51	
52	    const key = line.substring(0, colonIndex).trim();
53	    const value = line.substring(colonIndex + 1).trim();
54	
55	    if (key) {
56	      result[key] = parseYamlValue(value);
57	    }
58	  }
59	
60	  return result;
61	}
62	
63	export function parseFrontmatter(markdown: string): ParsedMarkdown {
64	  const lines = markdown.split('\n');
65	
66	  if (!lines[0]?.trim().startsWith('---')) {
67	    return {
68	      frontmatter: {},
69	      content: markdown,
70	    };
71	  }
72	
73	  let endIndex = -1;
74	  for (let i = 1; i < lines.length; i++) {
75	    if (lines[i]?.trim().startsWith('---')) {
76	      endIndex = i;
77	      break;
78	    }
79	  }
80	
81	  if (endIndex === -1) {
82	    return {
83	      frontmatter: {},
84	      content: markdown,
85	    };
86	  }
87	
88	  const yamlLines = lines.slice(1, endIndex);
89	  const yamlContent = yamlLines.join('\n');
90	  const content = lines.slice(endIndex + 1).join('\n').trim();
91	
92	  const parsed = parseYaml(yamlContent);
93	
94	  return {
95	    frontmatter: parsed as Frontmatter,
96	    content,
97	  };
98	}
