1	#!/usr/bin/env node
2	
3	import { build } from './generator';
4	import { DevServer } from './dev-server';
5	
6	async function main(): Promise<void> {
7	  const args = process.argv.slice(2);
8	
9	  if (args.length === 0) {
10	    console.error('Usage: ssg <command> [options]');
11	    console.error('Commands:');
12	    console.error('  build    Build the site');
13	    console.error('  serve    Start development server with live reload');
14	    process.exit(1);
15	  }
16	
17	  const command = args[0];
18	  let contentDir = './content';
19	  let outputDir = './dist';
20	  let templatesDir = './templates';
21	  let port = 3000;
22	
23	  for (let i = 1; i < args.length; i++) {
24	    if (args[i] === '--content' && args[i + 1]) {
25	      contentDir = args[i + 1];
26	      i++;
27	    } else if (args[i] === '--output' && args[i + 1]) {
28	      outputDir = args[i + 1];
29	      i++;
30	    } else if (args[i] === '--templates' && args[i + 1]) {
31	      templatesDir = args[i + 1];
32	      i++;
33	    } else if (args[i] === '--port' && args[i + 1]) {
34	      port = parseInt(args[i + 1], 10);
35	      i++;
36	    }
37	  }
38	
39	  try {
40	    if (command === 'build') {
41	      await build(contentDir, outputDir, templatesDir);
42	      console.log(`✓ Site built successfully to ${outputDir}`);
43	    } else if (command === 'serve') {
44	      await build(contentDir, outputDir, templatesDir);
45	      console.log(`✓ Initial build complete`);
46	      const devServer = new DevServer({ contentDir, outputDir, templatesDir, port });
47	      devServer.start();
48	    } else {
49	      console.error(`✗ Unknown command: ${command}`);
50	      console.error('Usage: ssg <command> [options]');
51	      console.error('Commands:');
52	      console.error('  build    Build the site');
53	      console.error('  serve    Start development server with live reload');
54	      process.exit(1);
55	    }
56	  } catch (error) {
57	    if (error instanceof Error) {
58	      console.error(`✗ Error: ${error.message}`);
59	    } else {
60	      console.error('✗ Unknown error occurred');
61	    }
62	    process.exit(1);
63	  }
64	}
65	
66	main();
