import { PageData } from './generator';

export interface PluginContext {
  contentDir: string;
  outputDir: string;
  templatesDir: string;
  [key: string]: unknown;
}

export interface Plugin {
  name: string;
  onStart?(context: PluginContext): Promise<void> | void;
  beforeBuild?(context: PluginContext): Promise<void> | void;
  onFile?(page: PageData, context: PluginContext): Promise<void> | void;
  afterBuild?(context: PluginContext, pages: PageData[]): Promise<void> | void;
  onEnd?(context: PluginContext): Promise<void> | void;
}

export class PluginManager {
  private plugins: Plugin[] = [];

  addPlugin(plugin: Plugin): void {
    this.plugins.push(plugin);
  }

  async executeHook(
    hookName: 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd',
    context: PluginContext,
    pages?: PageData[]
  ): Promise<void> {
    for (const plugin of this.plugins) {
      const hook = plugin[hookName];
      if (hook) {
        if (hookName === 'afterBuild' && pages !== undefined) {
          await (hook as (context: PluginContext, pages: PageData[]) => Promise<void>)(context, pages);
        } else {
          await (hook as (context: PluginContext) => Promise<void>)(context);
        }
      }
    }
  }

  async executeFileHook(page: PageData, context: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.onFile) {
        await plugin.onFile(page, context);
      }
    }
  }

  getPlugins(): Plugin[] {
    return this.plugins;
  }
}

import { Plugin, PluginContext } from '../plugin';
import { PageData } from '../generator';
import { markdownToHtml } from '../markdown';

export class MarkdownPlugin implements Plugin {
  name = 'markdown-plugin';

  async onFile(page: PageData, context: PluginContext): Promise<void> {
    if (page.html === '') {
      page.html = markdownToHtml(page.content);
    }
  }
}

import fs from 'fs';
import path from 'path';
import { Plugin, PluginContext } from '../plugin';
import { PageData } from '../generator';
import { TemplateEngine } from '../templates';

export interface TemplatePluginOptions {
  templatesDir?: string;
  layoutsDir?: string;
  partialsDir?: string;
}

export class TemplatePlugin implements Plugin {
  name = 'template-plugin';
  private templateEngine: TemplateEngine | undefined;
  private options: TemplatePluginOptions;

  constructor(options: TemplatePluginOptions = {}) {
    this.options = options;
  }

  async onStart(context: PluginContext): Promise<void> {
    const templatesDir = this.options.templatesDir || context.templatesDir || './templates';

    if (fs.existsSync(templatesDir)) {
      this.templateEngine = new TemplateEngine({
        templatesDir,
        layoutsDir: this.options.layoutsDir || path.join(templatesDir, 'layouts'),
        partialsDir: this.options.partialsDir || path.join(templatesDir, 'partials'),
      });
    }
  }

  async onFile(page: PageData, context: PluginContext): Promise<void> {
    if (!this.templateEngine) return;

    const templateName = String(page.frontmatter.template || 'page');
    const layoutName = String(page.frontmatter.layout || 'default');

    const templateContext = {
      title: page.frontmatter.title || page.slug,
      slug: page.slug,
      filename: page.filename,
      date: page.frontmatter.date,
      tags: page.frontmatter.tags,
      content: page.html,
      ...page.frontmatter,
    };

    const templateContent = this.templateEngine.renderTemplate(templateName, templateContext);

    if (this.templateEngine.hasLayout(layoutName)) {
      page.html = this.templateEngine.renderPageWithLayout(templateContent, layoutName, templateContext);
    } else {
      page.html = templateContent;
    }
  }

  getTemplateEngine(): TemplateEngine | undefined {
    return this.templateEngine;
  }
}

import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import { watch } from 'chokidar';
import { Plugin, PluginContext } from '../plugin';

export interface DevServerPluginOptions {
  port?: number;
}

let isBuilding = false;
let buildPending = false;

export class DevServerPlugin implements Plugin {
  name = 'dev-server-plugin';
  private server: http.Server | undefined;
  private wss: WebSocketServer | undefined;
  private port: number;
  private isRunning = false;
  private buildCallback: (() => Promise<void>) | undefined;

  constructor(options: DevServerPluginOptions = {}) {
    this.port = options.port || 3000;
  }

  async onStart(context: PluginContext): Promise<void> {
    const outputDir = context.outputDir as string;

    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    this.server = http.createServer((req, res) => this.handleRequest(req, res, outputDir));
    this.wss = new WebSocketServer({ server: this.server });

    const contentDir = context.contentDir as string;
    const templatesDir = context.templatesDir as string;

    const watcher = watch([contentDir, templatesDir], {
      ignored: /(^|[\/\\])\./,
      persistent: true,
    });

    watcher.on('change', () => {
      this.rebuild();
    });

    watcher.on('add', () => {
      this.rebuild();
    });

    watcher.on('unlink', () => {
      this.rebuild();
    });
  }

  async afterBuild(context: PluginContext): Promise<void> {
    if (this.isRunning) return;

    this.isRunning = true;
    this.server?.listen(this.port, () => {
      console.log(`\n🚀 Dev server running at http://localhost:${this.port}`);
      console.log(`📁 Watching ${context.contentDir} and ${context.templatesDir}`);
      console.log(`📦 Serving from ${context.outputDir}\n`);
    });
  }

  setBuildCallback(callback: () => Promise<void>): void {
    this.buildCallback = callback;
  }

  private async rebuild(): Promise<void> {
    if (!this.buildCallback) return;

    if (isBuilding) {
      buildPending = true;
      return;
    }

    isBuilding = true;
    try {
      console.log('🔄 Rebuilding...');
      await this.buildCallback();
      console.log('✓ Rebuild complete');
      this.notifyClients('rebuild-complete');

      if (buildPending) {
        buildPending = false;
        await this.rebuild();
      }
    } catch (error) {
      if (error instanceof Error) {
        console.error(`✗ Build error: ${error.message}`);
      } else {
        console.error('✗ Unknown build error');
      }
    } finally {
      isBuilding = false;
    }
  }

  private async handleRequest(req: http.IncomingMessage, res: http.ServerResponse, outputDir: string): Promise<void> {
    if (!req.url) {
      res.writeHead(404);
      res.end('Not found');
      return;
    }

    let filePath = req.url;
    if (filePath === '/') {
      filePath = 'index.html';
    } else if (filePath.startsWith('/')) {
      filePath = filePath.slice(1);
    }

    const fullPath = path.join(outputDir, filePath);

    if (!fs.existsSync(fullPath)) {
      res.writeHead(404);
      res.end('Not found');
      return;
    }

    let content = fs.readFileSync(fullPath, 'utf-8');

    if (filePath.endsWith('.html')) {
      content = this.injectLiveReloadScript(content);
    }

    const contentType = filePath.endsWith('.html') ? 'text/html' : 'application/octet-stream';
    res.writeHead(200, { 'Content-Type': contentType });
    res.end(content);
  }

  private injectLiveReloadScript(html: string): string {
    const script = `<script>
(function() {
  const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  const ws = new WebSocket(protocol + '//' + window.location.host);
  ws.onmessage = function(event) {
    if (event.data === 'rebuild-complete') {
      window.location.reload();
    }
  };
})();
</script>`;

    if (html.includes('</body>')) {
      return html.replace('</body>', `${script}</body>`);
    }
    return html + script;
  }

  private notifyClients(message: string): void {
    if (!this.wss) return;
    this.wss.clients.forEach((client: WebSocket) => {
      if (client.readyState === 1) {
        client.send(message);
      }
    });
  }

  stop(): void {
    this.server?.close();
    this.wss?.close();
  }
}

import fs from 'fs';
import path from 'path';
import { Plugin, PluginManager } from './plugin';

export interface PluginConfig {
  plugins: (Plugin | string)[];
}

async function loadPluginModule(pluginPath: string): Promise<Plugin> {
  if (path.isAbsolute(pluginPath)) {
    const module = await import(pluginPath);
    const DefaultExport = module.default;
    if (DefaultExport && typeof DefaultExport === 'function') {
      return new DefaultExport();
    }
    if (DefaultExport && typeof DefaultExport.name === 'string') {
      return DefaultExport;
    }
    throw new Error(`Invalid plugin module: ${pluginPath}`);
  } else {
    const module = await import(pluginPath);
    const DefaultExport = module.default;
    if (DefaultExport && typeof DefaultExport === 'function') {
      return new DefaultExport();
    }
    if (DefaultExport && typeof DefaultExport.name === 'string') {
      return DefaultExport;
    }
    throw new Error(`Invalid plugin module: ${pluginPath}`);
  }
}

export async function loadPluginsFromConfig(configPath: string): Promise<PluginManager> {
  const manager = new PluginManager();

  if (!fs.existsSync(configPath)) {
    return manager;
  }

  const configModule = await import(configPath);
  const config: PluginConfig = configModule.default || configModule;

  if (!config.plugins || !Array.isArray(config.plugins)) {
    return manager;
  }

  for (const pluginOrPath of config.plugins) {
    if (typeof pluginOrPath === 'string') {
      const plugin = await loadPluginModule(pluginOrPath);
      manager.addPlugin(plugin);
    } else if (pluginOrPath && typeof pluginOrPath === 'object' && 'name' in pluginOrPath) {
      manager.addPlugin(pluginOrPath as Plugin);
    }
  }

  return manager;
}

export function createPluginManager(plugins: Plugin[]): PluginManager {
  const manager = new PluginManager();
  for (const plugin of plugins) {
    manager.addPlugin(plugin);
  }
  return manager;
}

