    const outputPath = path.join(outputDir, `${pageData.slug}.html`);
    const html = templateEngine
      ? generatePageHtmlWithTemplate(pageData, templateEngine)
      : generatePageHtml(pageData);
    fs.writeFileSync(outputPath, html, 'utf-8');
  }

  return pages;
}

